- static struct dc_stream_state *
- create_stream_for_sink(struct drm_connector *connector,
- 		       const struct drm_display_mode *drm_mode,
- 		       const struct dm_connector_state *dm_state,
- 		       const struct dc_stream_state *old_stream,
- 		       int requested_bpc)
- {
- 	struct drm_device *dev = connector->dev;
- 	struct amdgpu_dm_connector *aconnector = NULL;
- 	struct drm_display_mode *preferred_mode = NULL;
- 	const struct drm_connector_state *con_state = &dm_state->base;
- 	struct dc_stream_state *stream = NULL;
- 	struct drm_display_mode mode;
- 	struct drm_display_mode saved_mode;
- 	struct drm_display_mode *freesync_mode = NULL;
- 	bool native_mode_found = false;
- 	bool recalculate_timing = false;
- 	bool scale = dm_state->scaling != RMX_OFF;
- 	int mode_refresh;
- 	int preferred_refresh = 0;
- 	enum color_transfer_func tf = TRANSFER_FUNC_UNKNOWN;
- #if defined(CONFIG_DRM_AMD_DC_FP)
- 	struct dsc_dec_dpcd_caps dsc_caps = {0};
- #endif
- 	struct dc_link *link = NULL;
- 	struct dc_sink *sink = NULL;
- 
- 	drm_mode_init(&mode, drm_mode);
- 	memset(&saved_mode, 0, sizeof(saved_mode));
- 
- 	if (connector->connector_type != DRM_MODE_CONNECTOR_WRITEBACK) {
- 		aconnector = NULL;
- 		aconnector = to_amdgpu_dm_connector(connector);
- 		link = aconnector->dc_link;
- 	} else {
- 		struct drm_writeback_connector *wbcon = NULL;
- 		struct amdgpu_dm_wb_connector *dm_wbcon = NULL;
- 
- 		wbcon = drm_connector_to_writeback(connector);
- 		dm_wbcon = to_amdgpu_dm_wb_connector(wbcon);
- 		link = dm_wbcon->link;
- 	}
- 
- 	if (!aconnector || !aconnector->dc_sink) {
- 		sink = create_fake_sink(dev, link);
- 		if (!sink)
- 			return stream;
- 
- 	} else {
- 		sink = aconnector->dc_sink;
- 		dc_sink_retain(sink);
- 	}
- 
- 	stream = dc_create_stream_for_sink(sink);
- 
- 	if (stream == NULL) {
- 		drm_err(dev, "Failed to create stream for sink!\n");
- 		goto finish;
- 	}
- 
- 	/* We leave this NULL for writeback connectors */
- 	stream->dm_stream_context = aconnector;
- 
- 	stream->timing.flags.LTE_340MCSC_SCRAMBLE =
- 		connector->display_info.hdmi.scdc.scrambling.low_rates;
- 
- 	list_for_each_entry(preferred_mode, &connector->modes, head) {
- 		/* Search for preferred mode */
- 		if (preferred_mode->type & DRM_MODE_TYPE_PREFERRED) {
- 			native_mode_found = true;
- 			break;
- 		}
- 	}
- 	if (!native_mode_found)
- 		preferred_mode = list_first_entry_or_null(
- 				&connector->modes,
- 				struct drm_display_mode,
- 				head);
- 
- 	mode_refresh = drm_mode_vrefresh(&mode);
- 
- 	if (preferred_mode == NULL) {
- 		/*
- 		 * This may not be an error, the use case is when we have no
- 		 * usermode calls to reset and set mode upon hotplug. In this
- 		 * case, we call set mode ourselves to restore the previous mode
- 		 * and the modelist may not be filled in time.
- 		 */
- 		drm_dbg_driver(dev, "No preferred mode found\n");
- 	} else if (aconnector) {
- 		recalculate_timing = amdgpu_freesync_vid_mode &&
- 				 is_freesync_video_mode(&mode, aconnector);
- 		if (recalculate_timing) {
- 			freesync_mode = get_highest_refresh_rate_mode(aconnector, false);
- 			drm_mode_copy(&saved_mode, &mode);
- 			saved_mode.picture_aspect_ratio = mode.picture_aspect_ratio;
- 			drm_mode_copy(&mode, freesync_mode);
- 			mode.picture_aspect_ratio = saved_mode.picture_aspect_ratio;
- 		} else {
- 			decide_crtc_timing_for_drm_display_mode(
- 					&mode, preferred_mode, scale);
- 
- 			preferred_refresh = drm_mode_vrefresh(preferred_mode);
- 		}
- 	}
- 
- 	if (recalculate_timing)
- 		drm_mode_set_crtcinfo(&saved_mode, 0);
- 
- 	/*
- 	 * If scaling is enabled and refresh rate didn't change
- 	 * we copy the vic and polarities of the old timings
- 	 */
- 	if (!scale || mode_refresh != preferred_refresh)
- 		fill_stream_properties_from_drm_display_mode(
- 			stream, &mode, connector, con_state, NULL,
- 			requested_bpc);
- 	else
- 		fill_stream_properties_from_drm_display_mode(
- 			stream, &mode, connector, con_state, old_stream,
- 			requested_bpc);
- 
- 	/* The rest isn't needed for writeback connectors */
- 	if (!aconnector)
- 		goto finish;
- 
- 	if (aconnector->timing_changed) {
- 		drm_dbg(aconnector->base.dev,
- 			"overriding timing for automated test, bpc %d, changing to %d\n",
- 			stream->timing.display_color_depth,
- 			aconnector->timing_requested->display_color_depth);
- 		stream->timing = *aconnector->timing_requested;
- 	}
- 
- #if defined(CONFIG_DRM_AMD_DC_FP)
- 	/* SST DSC determination policy */
- 	update_dsc_caps(aconnector, sink, stream, &dsc_caps);
- 	if (aconnector->dsc_settings.dsc_force_enable != DSC_CLK_FORCE_DISABLE && dsc_caps.is_dsc_supported)
- 		apply_dsc_policy_for_stream(aconnector, sink, stream, &dsc_caps);
- #endif
- 
- 	update_stream_scaling_settings(dev, &mode, dm_state, stream);
- 
- 	fill_audio_info(
- 		&stream->audio_info,
- 		connector,
- 		sink);
- 
- 	update_stream_signal(stream, sink);
- 
- 	if (stream->signal == SIGNAL_TYPE_HDMI_TYPE_A ||
- 	    stream->signal == SIGNAL_TYPE_HDMI_FRL)
- 		mod_build_hf_vsif_infopacket(stream, &stream->vsp_infopacket, false, false);
- 
- 	if (stream->signal == SIGNAL_TYPE_DISPLAY_PORT ||
- 	    stream->signal == SIGNAL_TYPE_DISPLAY_PORT_MST ||
- 	    stream->signal == SIGNAL_TYPE_EDP) {
- 		const struct dc_edid_caps *edid_caps;
- 		unsigned int disable_colorimetry = 0;
- 
- 		if (aconnector->dc_sink) {
- 			edid_caps = &aconnector->dc_sink->edid_caps;
- 			disable_colorimetry = edid_caps->panel_patch.disable_colorimetry;
- 		}
- 
- 		//
- 		// should decide stream support vsc sdp colorimetry capability
- 		// before building vsc info packet
- 		//
- 		stream->use_vsc_sdp_for_colorimetry = stream->link->dpcd_caps.dpcd_rev.raw >= 0x14 &&
- 						      stream->link->dpcd_caps.dprx_feature.bits.VSC_SDP_COLORIMETRY_SUPPORTED &&
- 						      !disable_colorimetry;
- 
- 		if (stream->out_transfer_func.tf == TRANSFER_FUNCTION_GAMMA22)
- 			tf = TRANSFER_FUNC_GAMMA_22;
- 		mod_build_vsc_infopacket(stream, &stream->vsc_infopacket, stream->output_color_space, tf);
- 		aconnector->sr_skip_count = AMDGPU_DM_PSR_ENTRY_DELAY;
- 
- 	}
- finish:
- 	dc_sink_release(sink);
- 
- 	return stream;
- }
